503:         validate_unit_axis(local_axes[1])?;
504:         validate_unit_axis(local_axes[2])?;
505: 
506:         if dot(local_axes[0], local_axes[1]).abs() > AXIS_TOLERANCE
507:             || dot(local_axes[0], local_axes[2]).abs() > AXIS_TOLERANCE
508:             || dot(local_axes[1], local_axes[2]).abs() > AXIS_TOLERANCE
