1763: fn assemble_element_contribution(
1764:     global: &mut DenseMatrix,
1765:     node_i: usize,
1766:     node_j: usize,
1767:     element_stiffness: &Matrix12,
1768: ) {
1769:     let dof_map = element_dof_map(node_i, node_j);
1770:     for local_row in 0..ELEMENT_DOF {
1771:         let global_row = dof_map[local_row];
1772:         for local_col in 0..ELEMENT_DOF {
1773:             let global_col = dof_map[local_col];
1774:             global[global_row][global_col] += element_stiffness[local_row][local_col];
1775:         }
1776:     }
1777: }
