1779: fn multiply_transpose_left(stiffness: &Matrix12, transform: &Matrix12) -> Matrix12 {
1780:     let mut temp = [[0.0; ELEMENT_DOF]; ELEMENT_DOF];
1781:     for row in 0..ELEMENT_DOF {
1782:         for col in 0..ELEMENT_DOF {
1783:             for inner in 0..ELEMENT_DOF {
1784:                 temp[row][col] += stiffness[row][inner] * transform[inner][col];
1785:             }
1786:         }
1787:     }
1788: 
1789:     let mut result = [[0.0; ELEMENT_DOF]; ELEMENT_DOF];
1790:     for row in 0..ELEMENT_DOF {
1791:         for col in 0..ELEMENT_DOF {
1792:             for inner in 0..ELEMENT_DOF {
1793:                 result[row][col] += transform[inner][row] * temp[inner][col];
1794:             }
1795:         }
1796:     }
1797:     result
1798: }
