45: /// The structure of a symmetric global stiffness (compressed rows, ascending
46: /// columns, each entry with the index of its transpose).
47: #[derive(Debug, Clone, PartialEq, Eq)]
48: pub struct SparsePattern {
49:     dimension: usize,
50:     row_starts: Vec<usize>,
51:     columns: Vec<usize>,
52:     transpose: Vec<usize>,
53: }
