55: impl SparsePattern {
56:     /// The symmetric closure of `positions`, deduplicated. A pure function of
57:     /// the set of positions: their order and repetition do not matter.
58:     pub fn from_positions(
59:         dimension: usize,
60:         positions: impl IntoIterator<Item = (usize, usize)>,
61:     ) -> Result<Self, StructuralError> {
62:         let mut rows: Vec<Vec<usize>> = vec![Vec::new(); dimension];
63:         for (row, col) in positions {
64:             if row >= dimension || col >= dimension {
65:                 return Err(StructuralError::InvalidInput("pattern position"));
66:             }
67:             rows[row].push(col);
68:             if row != col {
69:                 rows[col].push(row);
70:             }
71:         }
72:         for row in &mut rows {
73:             row.sort_unstable();
74:             row.dedup();
75:         }
76:         Ok(Self::from_sorted_rows(dimension, rows))
77:     }
78: 
79:     /// From element connectivity: each element `(node_i, node_j)` couples the
80:     /// 12 DOFs of its two nodes (four 6×6 node blocks); each DOF in `diagonal`
81:     /// (a spring) adds its diagonal entry. Node `k` owns DOFs 6k..6k+5.
82:     pub fn from_connectivity(
83:         node_count: usize,
84:         elements: &[(usize, usize)],
85:         diagonal: &[usize],
86:     ) -> Result<Self, StructuralError> {
87:         let dimension = node_count
88:             .checked_mul(DOF_PER_NODE)
89:             .ok_or(StructuralError::InvalidInput("pattern dimension"))?;
90:         let mut neighbours: Vec<Vec<usize>> = vec![Vec::new(); node_count];
91:         for &(a, b) in elements {
92:             if a >= node_count || b >= node_count {
93:                 return Err(StructuralError::InvalidInput("pattern element node"));
94:             }
95:             neighbours[a].extend([a, b]);
96:             neighbours[b].extend([a, b]);
97:         }
98:         for list in &mut neighbours {
99:             list.sort_unstable();
100:             list.dedup();
101:         }
102:         let mut spring = vec![false; dimension];
103:         for &dof in diagonal {
104:             if dof >= dimension {
105:                 return Err(StructuralError::InvalidInput("pattern diagonal DOF"));
106:             }
107:             spring[dof] = true;
108:         }
109:         let mut rows = Vec::with_capacity(dimension);
110:         for (node, list) in neighbours.iter().enumerate() {
111:             for local in 0..DOF_PER_NODE {
112:                 let dof = node * DOF_PER_NODE + local;
113:                 let row: Vec<usize> = if list.is_empty() {
114:                     if spring[dof] {
115:                         vec![dof]
116:                     } else {
117:                         Vec::new()
118:                     }
119:                 } else {
120:                     // A node with an element couples to itself, so its
121:                     // diagonal (and any spring on it) is already present.
122:                     list.iter()
123:                         .flat_map(|&other| (0..DOF_PER_NODE).map(move |k| other * DOF_PER_NODE + k))
124:                         .collect()
125:                 };
126:                 rows.push(row);
127:             }
128:         }
129:         Ok(Self::from_sorted_rows(dimension, rows))
130:     }
