132:     /// Rows must be sorted, deduplicated and structurally symmetric.
133:     fn from_sorted_rows(dimension: usize, rows: Vec<Vec<usize>>) -> Self {
134:         let mut row_starts = Vec::with_capacity(dimension + 1);
135:         row_starts.push(0);
136:         let mut columns = Vec::new();
137:         for row in rows {
138:             columns.extend(row);
139:             row_starts.push(columns.len());
140:         }
141:         let mut pattern = Self {
142:             dimension,
143:             row_starts,
144:             columns,
145:             transpose: Vec::new(),
146:         };
147:         let mut transpose = Vec::with_capacity(pattern.columns.len());
148:         for row in 0..dimension {
149:             for index in pattern.row_range(row) {
150:                 let col = pattern.columns[index];
151:                 transpose.push(
152:                     pattern
153:                         .find(col, row)
154:                         .expect("the symmetric closure holds every transpose"),
155:                 );
156:             }
157:         }
158:         pattern.transpose = transpose;
159:         pattern
160:     }
