162:     pub fn dimension(&self) -> usize {
163:         self.dimension
164:     }
165:     /// Stored entries (both triangles and the diagonal).
166:     pub fn entry_count(&self) -> usize {
167:         self.columns.len()
168:     }
169:     /// Stored entries on or below the diagonal.
170:     pub fn lower_entry_count(&self) -> usize {
171:         (0..self.dimension)
172:             .map(|row| self.row(row).iter().filter(|&&col| col <= row).count())
173:             .sum()
174:     }
175:     /// The entry indices of row `row`.
176:     pub fn row_range(&self, row: usize) -> std::ops::Range<usize> {
177:         self.row_starts[row]..self.row_starts[row + 1]
178:     }
179:     /// The columns of row `row`, ascending.
180:     pub fn row(&self, row: usize) -> &[usize] {
181:         &self.columns[self.row_range(row)]
182:     }
183:     /// The entry index of `(row, col)`, if stored.
184:     pub fn find(&self, row: usize, col: usize) -> Option<usize> {
185:         if row >= self.dimension {
186:             return None;
187:         }
188:         let start = self.row_starts[row];
189:         self.row(row).binary_search(&col).ok().map(|k| start + k)
190:     }
191:     /// The column of entry `index`.
192:     pub fn column(&self, index: usize) -> usize {
193:         self.columns[index]
194:     }
195:     /// The entry index of the transpose of entry `index`.
196:     pub fn transpose(&self, index: usize) -> usize {
197:         self.transpose[index]
198:     }
199: }
