1117:         self.contributions.is_some()
1118:     }
1119:     fn validate_equations(&self) -> Result<(), StructuralError> {
1120:         validate_sparse(self)
1121:     }
1122:     fn row(&self, i: usize) -> impl Iterator<Item = (usize, f64)> + Clone + '_ {
1123:         self.stiffness.row(i)
1124:     }
1125:     fn prescribed_coupled(&self, i: usize) -> bool {
1126:         self.stiffness.row(i).any(|(j, k)| {
1127:             let position = self
1128:                 .prescribed_position
1129:                 .get(j)
1130:                 .copied()
1131:                 .unwrap_or(usize::MAX);
1132:             position != usize::MAX && k != 0.0 && self.prescribed[position].1 != 0.0
1133:         })
1134:     }
1135:     fn contribution_sums(&self) -> Result<Option<Self::Sums>, StructuralError> {
1136:         sparse_contribution_sums(self)
1137:     }
