1139:         &'b self,
1140:         sums: &'b Self::Sums,
1141:         i: usize,
1142:     ) -> impl Iterator<Item = (usize, &'b Expansion)> + Clone + 'b {
1143:         let pattern = &self.stiffness.pattern;
1144:         pattern
1145:             .row_range(i)
1146:             .map(move |index| (pattern.columns[index], &sums[index]))
1147:     }
1148:     fn load_fidelity(
1149:         &self,
1150:         u: &[f64],
1151:         terms: &[ForceTerm],
1152:     ) -> Result<LoadFidelityReport, StructuralError> {
1153:         audit_sparse_load_fidelity(self, u, terms)
1154:     }
1155:     fn formation_check<F>(
1156:         &self,
1157:         source: &FormationSource,
1158:         force_terms: Option<&[ForceTerm]>,
1159:         scale_exponents: &[i32],
1160:         u: &[f64],
1161:         solve: &F,
1162:     ) -> Option<FormationCheck>
1163:     where
1164:         F: Fn(&[f64]) -> Result<Vec<f64>, StructuralError>,
1165:     {
1166:         // The check re-forms the intended system from `source`; of the
1167:         // equations it reads only `force` and `free_dofs` (and the attempt's
1168:         // own factor, through `solve`), so it takes the same inputs in both
1169:         // representations. Its stiffness view is left empty.
1170:         let view = StructuralSystem {
1171:             stiffness: &[],
1172:             force: self.force,
1173:             free_dofs: self.free_dofs,
1174:             prescribed: self.prescribed,
1175:             contributions: None,
1176:             symmetry: None,
1177:         };
1178:         formation_check::check(&view, source, force_terms, scale_exponents, u, solve)
1179:     }
1180: }
