1725: /// A positive skyline factor of a sparse prepared system. Like
1726: /// `PositiveFactor`, it cannot be constructed or relabelled by callers.
1727: pub struct SparsePositiveFactor<'p, 's> {
1728:     prepared: &'p SparsePreparedSystem<'s>,
1729:     factor: ProfileFactor,
1730:     pivots: Vec<PivotEvidence>,
1731: }
